  const [leadStageFilter,setLeadStageFilter]=useState<LeadStage|"All">("All"); const [dealStageFilter,setDealStageFilter]=useState<Deal["stage"]|"All">("All"); const [taskStatusFilter,setTaskStatusFilter]=useState<TaskStatus|"All">("All");
  const [selectedLead,setSelectedLead]=useState<Lead|null>(null); const [selectedDeal,setSelectedDeal]=useState<Deal|null>(null); const [selectedTask,setSelectedTask]=useState<Task|null>(null); const [selectedCompany,setSelectedCompany]=useState<Company|null>(null);
