  const [liveTick,setLiveTick]=useState(0);
  const [notificationsPref,setNotificationsPref]=useState({customer:true,deal:true,task:true,system:true});
  const [customStatuses,setCustomStatuses]=useState(["Active","Inactive","Lead","Prospect","Archive"]); const [newStatus,setNewStatus]=useState("");
  const [customTags,setCustomTags]=useState(["VIP","Enterprise","High Value","New","At Risk","Follow-up"]); const [newTag,setNewTag]=useState("");
  const [savedViews,setSavedViews]=useState<Record<string,CustomerFilters>>({});
  const [customerColumns,setCustomerColumns]=useState(["company","status","health","deal","lastContact","tags"]);
  const [proOpen,setProOpen]=useState(false);
