  const saveView=()=>{const name=window.prompt("Save current customer view as:","My View");if(!name?.trim())return;const n=name.trim();setSavedViews(s=>({...s,[n]:filters}));mutations.saveView.mutate({id:`view-${Date.now()}`,name:n,filters});notify("Saved view created")};
  const loadView=(name:string)=>{const next=savedViews[name];if(!next)return;setFilters(normalizeFilters(next));setPage(1);setSection("Customers");notify(`Loaded ${name}`)};
