    <div className="grid gap-4 xl:grid-cols-3"><Card className="p-5 xl:col-span-2"><div className="flex items-center justify-between"><div><h3 className="font-semibold">CRM Intelligence</h3><p className="text-xs text-slate-500">Actionable signals from connected records</p></div><Badge><Sparkles className="mr-1 h-3 w-3"/> Live demo</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-3"><button onClick={()=>setSection("Customers")} className="rounded-2xl border border-amber-400/10 bg-amber-500/5 p-4 text-left"><p className="text-xs text-amber-200">⚠ Attention Required</p><p className="mt-2 font-medium">{allCustomers.filter(c=>c.health<70).length} customers are at risk.</p><p className="mt-1 text-xs text-slate-500">Create follow-ups from the customer workspace.</p></button><button onClick={()=>setSection("Deals")} className="rounded-2xl border border-emerald-400/10 bg-emerald-500/5 p-4 text-left"><p className="text-xs text-emerald-200">✓ Opportunity</p><p className="mt-2 font-medium">{deals.filter(d=>d.probability>=80&&d.stage!=="Won").length} high-probability deals need attention.</p><p className="mt-1 text-xs text-slate-500">Review deal risk and create tasks.</p></button><button onClick={()=>setSection("Customers")} className="rounded-2xl border border-indigo-400/10 bg-indigo-500/5 p-4 text-left"><p className="text-xs text-indigo-200">✦ Data Quality</p><p className="mt-2 font-medium">94% workspace quality score.</p><p className="mt-1 text-xs text-slate-500">Review missing and duplicate records.</p></button></div></Card><Card className="p-5"><div className="flex items-center justify-between"><h3 className="font-semibold">Recent Activity</h3><button className="text-xs text-indigo-300" onClick={()=>setSection("Analytics")}>View all</button></div><div className="mt-4 space-y-4">{activities.map(a=><div key={a.id} className="flex gap-3"><div className="mt-1 h-2 w-2 rounded-full bg-indigo-400"/><div><p className="text-sm">{a.title}</p><p className="text-xs text-slate-500">{a.timestamp}</p></div></div>)}</div></Card></div>
